const ee = require('@google/earthengine');
const privateKey = require('./.earthsense-436113-b294c5f5c2dc.json');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  // Arabian Sea bounding box (approximate)
  const arabianSea = ee.Geometry.Rectangle([45, 5, 80, 25]); // minLon, minLat, maxLon, maxLat

  const startDate = '2023-06-01';
  const endDate = '2023-06-30';

  const scale = 5000; // OISST resolution is ~0.25 degrees, so 5km scale is appropriate

  // 2. Data Acquisition & Check
  const sstCollection = ee.ImageCollection('NOAA/AVHRR/OISST/V2').select('sst')
    .filterDate(startDate, endDate)
    .filterBounds(arabianSea);

  const collectionSize = await sstCollection.size().getInfo();
  console.log(`June 2023 OISST images: ${collectionSize}`);

  if (collectionSize === 0) {
    console.log("No OISST data found for June 2023 in the Arabian Sea.");
    console.log("C1");
    return;
  }

  // Compute the maximum SST over the entire period for the region
  // OISST values are often in Celsius * 100, so divide by 100.
  // Check the dataset description: 'sst' (Sea surface temperature) in degrees Kelvin * 100.
  // Convert to Celsius: (K / 100) - 273.15
  const maxSstImageKelvin = sstCollection.reduce(ee.Reducer.max());

  // Convert Kelvin*100 to Celsius
  const maxSstImageCelsius = maxSstImageKelvin.divide(100).subtract(273.15);

  // 3. Processing (Calculate pixel count to detect C2)
  const stats = await maxSstImageCelsius.reduceRegion({
    reducer: ee.Reducer.max().combine({
      reducer2: ee.Reducer.count(),
      sharedInputs: true
    }),
    geometry: arabianSea,
    scale: scale,
    maxPixels: 1e9,
    tileScale: 16 // Increased tileScale for potentially large regions
  }).getInfo();

  const maxSst = stats ? stats['sst_max'] : null;
  const pixelCount = stats ? stats['sst_count'] : 0;

  console.log(`Valid pixels: ${pixelCount}`);

  if (pixelCount === 0) {
    console.log("No valid pixels remain after processing for max SST.");
    console.log("C2");
    return;
  }

  // 4. Calculation and Validation & Final Answer
  if (maxSst === null || isNaN(maxSst)) {
    console.log("Calculation of maximum SST failed (result is null or NaN).");
    console.log("C3");
    return;
  }

  const threshold = 30.0;
  console.log(`Max SST in Arabian Sea (June 2023): ${maxSst.toFixed(2)} °C`);

  if (maxSst >= threshold) {
    console.log("A"); // Yes
  } else {
    console.log("B"); // No
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
